@startuml

class WebPortal {
  + versionNumber : string
  + url : string
}

class Building {
  + id : string
  + name : string
  + address : string
  + yearOfConstruction : int
}

class Entry {
  + name : string
  + public : boolean
}

class TextEntry {
  + text : string
}

class NumericEntry {
  + value : float
  + unit : string
}

class Image {
  + fileName : string
}

class User {
  + username : string
  + email : string
  + password : string
}

class Administrator {
  + idCardNumber : string
}

class Comment {
  + text : string
}

enum EnergyClass {
  A
  B
  C
  D
}

User <|-- Administrator

WebPortal "1" -- "*" Building
WebPortal "1" -- "*" User
Building "1" -- "1" EnergyClass
Building "1" -- "1" Image : profile photo
Building "1" *-- "*" Image
Building "1" *-- "*" Entry
Building "1" -- "1" User : owner
User "1" -- "*" Building : creates
User "1" -- "*" Comment : writes
User "1" -- "*" Building : comments on
User "1" -- "*" Entry : manages

Entry <|-- TextEntry
Entry <|-- NumericEntry

@enduml

